const workerHello = `-- name: WorkerHello :exec
UPDATE workers SET last_seen_at = now(), version = $1, capabilities = $2 WHERE id = $3
`

type WorkerHelloParams struct {
	Version      pgtype.Text
	Capabilities []byte
	ID           uuid.UUID
}

func (q *Queries) WorkerHello(ctx context.Context, arg WorkerHelloParams) error {
	_, err := q.db.Exec(ctx, workerHello, arg.Version, arg.Capabilities, arg.ID)
	return err
}

const workerTaskCounts = `-- name: WorkerTaskCounts :one
SELECT count(*) FILTER (WHERE state = 'queued')::bigint AS waiting,
       coalesce((SELECT max(last_seen_at) FROM workers WHERE revoked_at IS NULL), 'epoch')::timestamptz AS last_seen -- epoch: never
FROM worker_tasks
`

type WorkerTaskCountsRow struct {
	Waiting  int64
	LastSeen time.Time
}

// AI work for the health check: tasks waiting for a worker, and the latest a worker checked in.
func (q *Queries) WorkerTaskCounts(ctx context.Context) (WorkerTaskCountsRow, error) {
	row := q.db.QueryRow(ctx, workerTaskCounts)
	var i WorkerTaskCountsRow
	err := row.Scan(&i.Waiting, &i.LastSeen)
	return i, err
}
